def verify():
    assert abs(50 * 0.87 * 0.8 - 34.8) < 1e-9 and abs(58 / 58 / 2.5 - 0.4) < 1e-12
    assert abs(35.6 * 20 * 20 / 4000 - 3.56) < 1e-9 and abs(30.8 * 50 * 30 / 10000 - 4.62) < 1e-9 and abs(17.8 * 600 / 6000 - 1.78) < 1e-9
    assert abs(500 * 0.6 / (1.2 * 0.8) - 312.5) < 1e-9
    In = 1e6 / (math.sqrt(3) * 380); assert abs(20 * In / 1000 - 30.39) < 0.01
    assert abs(500 * 100 / (5000 * 0.5 * 0.8) - 25) < 1e-9 and abs(15000 / (math.sqrt(3) * 380 * 0.9 * 0.85) - 29.8) < 0.05
    assert abs(math.sqrt(3) * 380 * 20 / 1000 - 13.16) < 0.01


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
